import { drizzle } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import { fileURLToPath } from "node:url";
import pg from "pg";
import * as schema from "./schema.js";

/** SQL migrations generated by drizzle-kit (`pnpm db:generate`), same path from src/ and dist/. */
const MIGRATIONS_FOLDER = fileURLToPath(new URL("../../drizzle", import.meta.url));

export type Database = ReturnType<typeof createDatabase>["db"];

/**
 * A connection POOL, not a single connection: queries from many requests run in
 * parallel on a few reused connections instead of opening a new one each time.
 */
export function createDatabase(connectionString: string) {
  const pool = new pg.Pool({ connectionString, max: 10 });
  const db = drizzle(pool, { schema });

  return {
    db,
    /** Applies migrations that haven't run yet (tracked by drizzle in its own table). */
    migrate: () => migrate(db, { migrationsFolder: MIGRATIONS_FOLDER }),
    close: () => pool.end(),
  };
}
